import { createRoot } from "react-dom/client";
import { HashRouter, Route, Routes } from "react-router-dom";

import { App } from "./todo/app";
import "todomvc-app-css/index.css";
import "todomvc-common/base.css";

createRoot(document.getElementById("root")).render(
    <HashRouter>
        <Routes>
            <Route path="*" element={<App />} />
        </Routes>
    </HashRouter>
);

/* used for things that should be hidden in the ui,
but useful for people who use screen readers */
.visually-hidden {
    border: 0;
    clip: rect(0 0 0 0);
    clip-path: inset(50%);
    height: 1px;
    width: 1px;
    margin: -1px;
    padding: 0;
    overflow: hidden;
    position: absolute;
    white-space: nowrap;
}

.toggle-all {
    width: 40px !important;
    height: 60px !important;
    right: auto !important;
}

.toggle-all-label {
    pointer-events: none;
}

import { useReducer } from "react";
import { Header } from "./components/header";
import { Main } from "./components/main";
import { Footer } from "./components/footer";

import { todoReducer } from "./reducer";

import "./app.css";

export function App() {
    const [todos, dispatch] = useReducer(todoReducer, []);

    return (
        <>
            <Header dispatch={dispatch} />
            <Main todos={todos} dispatch={dispatch} />
            <Footer todos={todos} dispatch={dispatch} />
        </>
    );
}

import { useCallback, useMemo } from "react";
import { useLocation } from "react-router-dom";
import classnames from "classnames";

import { REMOVE_COMPLETED_ITEMS } from "../constants";

export function Footer({ todos, dispatch }) {
    const { pathname: route } = useLocation();

    const activeTodos = useMemo(() => todos.filter((todo) => !todo.completed), [todos]);
    const completedCount = todos.length - activeTodos.length;

    const removeCompleted = useCallback(() => dispatch({ type: REMOVE_COMPLETED_ITEMS }), [dispatch]);

    return (
        <footer className="footer" data-testid="footer" hidden={todos.length === 0}>
            <span className="todo-count">{`${activeTodos.length} ${activeTodos.length === 1 ? "item" : "items"} left!`}</span>
            <ul className="filters" data-testid="footer-navigation">
                <li>
                    <a className={classnames({ selected: route === "/" })} href="#/">All</a>
                </li>
                <li>
                    <a className={classnames({ selected: route === "/active" })} href="#/active">Active</a>
                </li>
                <li>
                    <a className={classnames({ selected: route === "/completed" })} href="#/completed">Completed</a>
                </li>
            </ul>
            <button
                className="clear-completed"
                hidden={completedCount === 0}
                onClick={removeCompleted}
            >
                Clear completed
            </button>
        </footer>
    );
}

import { useCallback } from "react";
import { Input } from "./input";

import { ADD_ITEM } from "../constants";

export function Header({ dispatch }) {
    const addItem = useCallback((title) => dispatch({ type: ADD_ITEM, payload: { title } }), [dispatch]);

    return (
        <header className="header" data-testid="header">
            <h1>todos</h1>
            <Input onSubmit={addItem} label="New Todo Input" placeholder="What needs to be done?" />
        </header>
    );
}

import { useCallback } from "react";

export function Input({ onSubmit, placeholder, label, defaultValue, onBlur, editing = false }) {
    const handleBlur = useCallback(
        (e) => {
            if (!onBlur) return;
            const value = e.target.value.trim();
            onBlur(value);
        },
        [onBlur]
    );

    const handleKeyDown = useCallback(
        (e) => {
            if (e.key !== "Enter") return;
            const value = e.target.value.trim();
            // For new-todo, ignore empty submits. For edit, an empty
            // submit means "delete this todo" — let the parent decide.
            if (!editing && value.length === 0) return;
            onSubmit(value);
            // Only clear the new-todo input on submit; the edit input is
            // about to unmount so leave it alone.
            if (!editing) e.target.value = "";
        },
        [onSubmit, editing]
    );

    return (
        <input
            className={editing ? "edit" : "new-todo"}
            type="text"
            data-testid="text-input"
            autoFocus
            aria-label={label}
            placeholder={placeholder}
            defaultValue={defaultValue}
            onBlur={handleBlur}
            onKeyDown={handleKeyDown}
        />
    );
}

import { memo, useState, useCallback } from "react";
import classnames from "classnames";

import { Input } from "./input";

import { TOGGLE_ITEM, REMOVE_ITEM, UPDATE_ITEM } from "../constants";

export const Item = memo(function Item({ todo, dispatch }) {
    const [isWritable, setIsWritable] = useState(false);
    const { title, completed, id } = todo;

    const toggleItem = useCallback(() => dispatch({ type: TOGGLE_ITEM, payload: { id } }), [dispatch, id]);
    const removeItem = useCallback(() => dispatch({ type: REMOVE_ITEM, payload: { id } }), [dispatch, id]);
    const updateItem = useCallback(
        (newTitle) => dispatch({ type: UPDATE_ITEM, payload: { id, title: newTitle } }),
        [dispatch, id]
    );

    const handleDoubleClick = useCallback(() => setIsWritable(true), []);

    const commitEdit = useCallback(
        (newTitle) => {
            // Only act once per edit session — Enter then blur would
            // otherwise dispatch twice.
            if (!isWritable) return;
            setIsWritable(false);
            if (newTitle.length === 0) removeItem();
            else updateItem(newTitle);
        },
        [isWritable, removeItem, updateItem]
    );

    return (
        <li className={classnames({ completed, editing: isWritable })} data-testid="todo-item">
            <div className="view">
                <input
                    className="toggle"
                    type="checkbox"
                    data-testid="todo-item-toggle"
                    checked={completed}
                    onChange={toggleItem}
                />
                <label data-testid="todo-item-label" onDoubleClick={handleDoubleClick}>
                    {title}
                </label>
                <button
                    className="destroy"
                    data-testid="todo-item-button"
                    aria-label="Delete todo"
                    onClick={removeItem}
                />
            </div>
            {isWritable && (
                <Input
                    editing
                    onSubmit={commitEdit}
                    onBlur={commitEdit}
                    label="Edit todo"
                    defaultValue={title}
                />
            )}
        </li>
    );
});

import { useMemo, useCallback } from "react";
import { useLocation } from "react-router-dom";

import { Item } from "./item";

import { TOGGLE_ALL } from "../constants";

export function Main({ todos, dispatch }) {
    const { pathname: route } = useLocation();

    const visibleTodos = useMemo(
        () =>
            todos.filter((todo) => {
                if (route === "/active")
                    return !todo.completed;

                if (route === "/completed")
                    return todo.completed;

                return todo;
            }),
        [todos, route]
    );

    const toggleAll = useCallback((e) => dispatch({ type: TOGGLE_ALL, payload: { completed: e.target.checked } }), [dispatch]);

    return (
        <main className="main" data-testid="main" hidden={todos.length === 0}>
            <div className="toggle-all-container">
                <input
                    className="toggle-all"
                    type="checkbox"
                    id="toggle-all"
                    data-testid="toggle-all"
                    checked={visibleTodos.length > 0 && visibleTodos.every((todo) => todo.completed)}
                    onChange={toggleAll}
                />
                <label className="toggle-all-label" htmlFor="toggle-all">
                    Toggle All Input
                </label>
            </div>
            <ul className="todo-list" data-testid="todo-list">
                {visibleTodos.map((todo) => (
                    <Item todo={todo} key={todo.id} dispatch={dispatch} />
                ))}
            </ul>
        </main>
    );
}

export const ADD_ITEM = "ADD_ITEM";
export const UPDATE_ITEM = "UPDATE_ITEM";
export const REMOVE_ITEM = "REMOVE_ITEM";
export const TOGGLE_ITEM = "TOGGLE_ITEM";
export const REMOVE_ALL_ITEMS = "REMOVE_ALL_ITEMS";
export const TOGGLE_ALL = "TOGGLE_ALL";
export const REMOVE_COMPLETED_ITEMS = "REMOVE_COMPLETED_ITEMS";

import { ADD_ITEM, UPDATE_ITEM, REMOVE_ITEM, TOGGLE_ITEM, REMOVE_ALL_ITEMS, TOGGLE_ALL, REMOVE_COMPLETED_ITEMS } from "./constants";

