import { useCallback } from "react";

export function Input({ onSubmit, placeholder, label, defaultValue, onBlur, editing = false, onCancel }) {
    const handleBlur = useCallback(
        (e) => {
            if (!onBlur) return;
            const value = e.target.value.trim();
            onBlur(value);
        },
        [onBlur]
    );

    const handleKeyDown = useCallback(
        (e) => {
            if (e.key === "Enter") {
                const value = e.target.value.trim();
                if (!editing && value.length === 0) return;
                onSubmit(value);
                if (!editing) e.target.value = "";
                return;
            }
            if (e.key === "Escape" && onCancel) {
                onCancel();
            }
        },
        [onSubmit, editing, onCancel]
    );

    return (
        <input
            className={editing ? "edit" : "new-todo"}
            type="text"
            data-testid="text-input"
            autoFocus
            aria-label={label}
            placeholder={placeholder}
            defaultValue={defaultValue}
            onBlur={handleBlur}
            onKeyDown={handleKeyDown}
        />
    );
}

